    ],
    'faqs' => [
      ['q' => 'What is the September 1 lease cycle?', 'a' => 'Many Boston and Cambridge leases start and end on September 1. A summer sublet lets you arrive earlier and search for a full lease on the local schedule.'],
      ['q' => 'Do I need a car in Cambridge?', 'a' => 'No. The Red Line, buses and bike lanes make car-free living common, and parking is limited and costly.'],
