      ['q' => 'How far is College Station from Houston?', 'a' => 'Roughly 90 miles, or about an hour and a half to two hours by car depending on traffic.'],
      ['q' => 'When are football weekends?', 'a' => 'Home games at Kyle Field happen on fall weekends. Short-term rentals and hotels fill quickly, so plan around them.'],
    ],
